<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {api,can,operationAvailable,ifxTableAddress,type Configuration,type Tank,type ControlRecord,type InstrumentCommand,type LiveReading} from './api';
import GatewayControlStatus from './GatewayControlStatus.vue';
import {instrumentMode} from './instrumentMode';
import UiIcon from './UiIcon.vue';
const props=defineProps<{licensed:boolean;config:Configuration;tank:Tank;canOperate:boolean;dirty:boolean;compact?:boolean;hideRemoteLevel?:boolean;reading?:LiveReading;readingValid?:boolean}>();
const channelProtocol=computed(()=>props.config.channels.find(c=>c.id===props.tank.channelId)?.protocol);
const currentMode=computed(()=>instrumentMode(props.reading,props.readingValid===true,channelProtocol.value));
const isGateway=computed(()=>['GatewayTcp','GatewayRtu'].includes(channelProtocol.value||''));
const reviewMode=ref<'review'|'reset'>('review');
const targetLevelMm=ref<number|null>(null),adjustmentReason=ref('');
const permission=(c:InstrumentCommand)=>c==='Stop'?'InstrumentStop':c==='RemoteLevel'?'RemoteLevelAdjust':'InstrumentControl';
const showResults=ref(false),resultDialog=ref(false);
const rows=ref<ControlRecord[]>([]),action=ref<InstrumentCommand|null>(null),review=ref<ControlRecord|null>(null),confirmed=ref(false),reason=ref(''),error=ref(''),message=ref(''),busy=ref(false);let timer:ReturnType<typeof setInterval>|undefined;
const names:Record<InstrumentCommand,string>={MeasureI:'测量Ⅰ',MeasureII:'测量Ⅱ（界面）',MeasureIII:'测量Ⅲ（罐底）',Stop:'停止',Hoist:'上升',Lower:'下降',Density:'远程密度',Repeatability:'重复性检查',OscillationAvoidance:'液体震荡回避',RemoteLevel:'远程液位修改'};
function recordName(r:ControlRecord){return r.isReset?(r.cycle==='Normal'?'正常动作结果通道':'独立停止结果通道'):r.command?names[r.command]:'原命令未记录'}
const states:Record<string,string>={Prepared:'待处理',Queued:'已受理',Checking:'核验中',WriteIntent:'已记录待写入',Submitted:'已提交，等待回读',ReadbackConfirmed:'回读已确认',Rejected:'拒绝或失败',Unknown:'结果未知 · 需核查',Reviewed:'人工核查已记录'};
const pendingStates=['Prepared','Queued','Checking','WriteIntent','Submitted','Unknown'];
const pendingRows=computed(()=>rows.value.filter(r=>pendingStates.includes(r.state)));
const pending=computed(()=>pendingRows.value.length>0);
const recordLimit=ref(10),focusedRecordId=ref<string|null>(null);
const gatewayStatus=ref<InstanceType<typeof GatewayControlStatus>|null>(null);
const displayedRecords=computed(()=>focusedRecordId.value?rows.value.filter(r=>r.id===focusedRecordId.value):rows.value.slice(0,recordLimit.value));
function openResults(id?:string){focusedRecordId.value=id||null;recordLimit.value=10;resultDialog.value=true;showResults.value=true;void load()}
const commands=computed(()=>{const list=[...props.tank.controls.allowedCommands];if(pending.value&&!list.includes('Stop'))list.push('Stop');return list.filter(c=>operationAvailable(c)&&can(permission(c)))});
async function load(){const tankId=props.tank.id;try{
 const [recent,unresolved]=await Promise.all([
  api<ControlRecord[]>('/api/controls?tank='+props.tank.id),
  api<ControlRecord[]>('/api/controls?tank='+props.tank.id+'&unresolved=true')
 ]);
 if(props.tank.id!==tankId)return;
 const merged=new Map(recent.map(r=>[r.id,r]));for(const r of unresolved)merged.set(r.id,r);
 rows.value=[...merged.values()].sort((a,b)=>Number(pendingStates.includes(b.state))-Number(pendingStates.includes(a.state))||Date.parse(b.createdAtUtc)-Date.parse(a.createdAtUtc));
}catch(e){error.value=String(e)}}
function open(c:InstrumentCommand){if(!props.licensed&&!['Stop','MeasureI'].includes(c)){error.value='当前授权不允许新动作';return}if(props.dirty){error.value='请先保存或重新载入待保存配置';return}action.value=c;targetLevelMm.value=null;adjustmentReason.value='';confirmed.value=false;error.value=''}
async function execute(){if(!action.value||busy.value)return;busy.value=true;try{await api('/api/tanks/'+props.tank.id+'/controls','POST',{configurationRevision:props.config.revision,command:action.value,confirmed:confirmed.value,...(action.value==='RemoteLevel'?{targetLevelMm:targetLevelMm.value,reason:adjustmentReason.value}: {})});action.value=null;showResults.value=true;if(props.compact)resultDialog.value=true;message.value=isGateway.value?'操作已受理；本次明确结果保存后系统自动清除对应结果通道，异常待核查时保留。':'操作已受理，请查看操作记录与回读结果。';await load()}catch(e){error.value=String(e);await load();void gatewayStatus.value?.refresh()}finally{busy.value=false}}
function openReview(r:ControlRecord,mode:'review'|'reset'='review'){resultDialog.value=false;reviewMode.value=mode;review.value=r;reason.value='';confirmed.value=false;error.value=''}
async function saveReview(){if(!review.value||busy.value)return;busy.value=true;try{await api('/api/controls/'+review.value.id+'/'+reviewMode.value,'POST',{reason:reason.value,confirmed:confirmed.value});review.value=null;showResults.value=true;if(props.compact)resultDialog.value=true;message.value=reviewMode.value==='reset'?'复位请求已受理，仅清除选定结果通道，未停止或重发动作。':'人工核查已记录，未停止、复位或重发动作。';await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
defineExpose({openRemoteLevel:()=>open('RemoteLevel')});
watch(()=>props.tank.id,()=>{rows.value=[];error.value='';message.value='';focusedRecordId.value=null;resultDialog.value=false;action.value=null;review.value=null;void load()});
onMounted(()=>{void load();timer=setInterval(()=>void load(),1500)});onUnmounted(()=>{if(timer)clearInterval(timer)});
</script>
<template><section v-if="commands.length||rows.length||isGateway||reading" class="panel instrument-controls"><div class="instrument-heading"><h3>仪表操作</h3><span class="instrument-mode" aria-label="当前仪表模式">当前模式：{{currentMode}}</span></div><p v-if="!licensed" class="help">当前授权保留停止及必要恢复测量Ⅰ。已在测量Ⅰ时，不重复发送恢复命令。</p><div class="control-buttons" :class="{'dense-controls':compact&&commands.length>4}"><button v-for="c in commands.filter(c=>!compact||c!=='RemoteLevel')" :key="c" class="button" :class="{'stop-command':c==='Stop'}" :disabled="!can(permission(c))||busy||!licensed&&!(['Stop','MeasureI'].includes(c))" @click="open(c)"><UiIcon v-if="c==='Stop'" name="stop"/>{{names[c]}}</button></div><GatewayControlStatus v-if="isGateway" :key="tank.id+'-'+tank.channelId" :tank="tank" :config="config" ref="gatewayStatus" :dirty="dirty" :records="rows" @changed="load" @view-record="openResults"/><p v-if="error&&!action&&!review" role="alert" class="error-message">{{error}}</p><p v-if="message" role="status" class="help">{{message}}</p><p v-if="pending" class="help error-message">{{tank.code}} 有 {{pendingRows.length}} 条执行中或待核查记录。</p><button v-if="compact&&!hideRemoteLevel&&commands.includes('RemoteLevel')" class="text-button" :disabled="busy||!licensed" @click="open('RemoteLevel')">远程液位修改 →</button><button v-if="compact" class="text-button compact-control-records" @click="openResults()">操作记录与回读（{{rows.length}}） →</button><details v-else :open="pending||showResults"><summary>近期操作与回读</summary><button v-if="focusedRecordId" type="button" class="text-button" @click="focusedRecordId=null">查看全部操作记录</button><p class="help control-record-summary">执行中 / 待核查 {{pendingRows.length}} 项（优先显示） · 已显示 {{displayedRecords.length}} / {{rows.length}} 条载入记录</p><div v-for="r in displayedRecords" :key="r.id" class="control-result"><strong>{{r.isAutomaticReset?'系统自动复位 · ':r.isReset?'人工复位（无动作） · ':''}}{{recordName(r)}} · {{r.isReset&&r.state==='ReadbackConfirmed'?'结果通道复位已确认':states[r.state]}}</strong><small>{{new Date(r.createdAtUtc).toLocaleString('zh-CN',{hour12:false})}} · {{r.actorName}}</small><p>{{r.result}}</p><template v-if="r.command==='RemoteLevel'&&!r.isReset"><p>目标液位 {{r.targetLevelMm}} mm · 原因：{{r.adjustmentReason}}</p><p v-if="r.levelAdjustment?.newOffsetMm!=null" class="help">修改前液位 {{r.levelAdjustment.currentLevelMm}} mm · 原偏移 {{r.levelAdjustment.previousOffsetMm}} mm · 新偏移 {{r.levelAdjustment.newOffsetMm}} mm · 回读 {{r.levelAdjustment.readbackOffsetMm??'未确认'}} mm</p><p v-if="r.levelAdjustment?.authorizationClearConfirmed!=null" class="help">认证清零：{{r.levelAdjustment.authorizationClearConfirmed?'已确认':'未确认，须核查仪表'}}</p></template><button v-if="r.state==='Unknown'&&can('ControlReview')" class="text-button" @click="openReview(r)">人工核查记录</button></div><button v-if="displayedRecords.length<rows.length" class="text-button control-record-more" @click="recordLimit+=20">显示更多操作记录</button></details></section><div v-if="compact&&resultDialog" class="modal-backdrop"><section class="modal control-record-dialog" role="dialog" aria-label="操作记录与回读"><div class="modal-head"><h2>{{tank.code}} · 操作记录与回读</h2><button class="button" @click="resultDialog=false">关闭</button></div><div class="modal-body"><button v-if="focusedRecordId" type="button" class="text-button" @click="focusedRecordId=null">查看全部操作记录</button><p class="help control-record-summary">执行中 / 待核查 {{pendingRows.length}} 项（优先显示） · 已显示 {{displayedRecords.length}} / {{rows.length}} 条载入记录</p><div v-for="r in displayedRecords" :key="r.id" class="control-result"><strong>{{r.isAutomaticReset?'系统自动复位 · ':r.isReset?'人工复位（无动作） · ':''}}{{recordName(r)}} · {{r.isReset&&r.state==='ReadbackConfirmed'?'结果通道复位已确认':states[r.state]}}</strong><small>{{new Date(r.createdAtUtc).toLocaleString('zh-CN',{hour12:false})}} · {{r.actorName}}</small><p>{{r.result}}</p><template v-if="r.command==='RemoteLevel'&&!r.isReset"><p>目标液位 {{r.targetLevelMm}} mm · 原因：{{r.adjustmentReason}}</p><p v-if="r.levelAdjustment?.newOffsetMm!=null" class="help">修改前液位 {{r.levelAdjustment.currentLevelMm}} mm · 原偏移 {{r.levelAdjustment.previousOffsetMm}} mm · 新偏移 {{r.levelAdjustment.newOffsetMm}} mm · 回读 {{r.levelAdjustment.readbackOffsetMm??'未确认'}} mm</p><p v-if="r.levelAdjustment?.authorizationClearConfirmed!=null" class="help">认证清零：{{r.levelAdjustment.authorizationClearConfirmed?'已确认':'未确认，须核查仪表'}}</p></template><button v-if="r.state==='Unknown'&&can('ControlReview')" class="text-button" @click="openReview(r)">人工核查记录</button></div><button v-if="displayedRecords.length<rows.length" class="text-button control-record-more" @click="recordLimit+=20">显示更多操作记录</button><p v-if="!rows.length" class="help">暂无操作记录。</p></div></section></div><div v-if="action||review" class="modal-backdrop"><section class="modal" role="dialog" :aria-label="action?'确认仪表操作':'人工核查仪表操作'"><div class="modal-head"><h2>{{action?'确认仪表操作':'人工核查仪表操作'}}</h2><button class="button" @click="action=null;review=null">关闭</button></div><div class="modal-body"><p v-if="error" role="alert" class="error-message">{{error}}</p><div class="notice"><strong>{{tank.code}} · {{action?names[action]:recordName(review!)}}</strong><p>{{config.channels.find(c=>c.id===tank.channelId)?.name}} · {{channelProtocol==='IfxL25'?'表地址':'仪表地址'}} {{channelProtocol==='IfxL25'?ifxTableAddress(tank.address,config.channels.find(c=>c.id===tank.channelId)!.unitId):tank.address}}</p></div><form v-if="action" @submit.prevent="execute"><p class="help">{{action==='RemoteLevel'?'将按目标液位计算并修改仪表的液位偏移参数。请核对现场液位和浮子稳定状态；结果不确定时须人工核查，不会自动重复修改。':'将向已绑定的实际仪表发送该操作。写入回执及模式回读不能代替机械到位；结果不确定时不会自动重发。'}}</p><template v-if="action==='RemoteLevel'"><label class="config-field">目标液位 mm<input v-model.number="targetLevelMm" type="number" min="-9999.9" max="99999.9" step="0.1" required placeholder="输入现场核实后的液位"></label><label class="config-field">修改原因<textarea v-model="adjustmentReason" required maxlength="1000" rows="2" placeholder="填写现场核查依据及修改原因"></textarea></label></template><label class="checkbox"><input v-model="confirmed" type="checkbox" required>{{action==='RemoteLevel'?'已核对储罐、目标液位和现场条件，确认修改仪表参数':'已核对储罐、操作和现场条件，确认执行'}}</label><button class="button primary" :disabled="!confirmed||busy||!can(permission(action))">确认执行 {{names[action]}}</button></form><form v-else @submit.prevent="saveReview"><p class="help">先核对现场浮子运动、实际位置、仪表模式及原动作。{{reviewMode==='reset'?(review?.command==='RemoteLevel'?'本操作仅清除网关结果，不恢复原偏移、不重写液位，也不替仪表清认证；须先核查实际偏移和认证状态。':'本操作写0复位选定的网关结果通道，不停止浮子、不重发动作；另一通道结果继续保留。'):'本操作只保存核查结论，不停止、不复位、不重发动作。'}}</p><label class="config-field">现场核查结论<textarea v-model="reason" rows="4" required maxlength="1000"></textarea></label><label class="checkbox"><input v-model="confirmed" type="checkbox" required>已完成现场核对，确认记录核查结果</label><button class="button primary" :disabled="!confirmed||!reason.trim()||busy">{{reviewMode==='reset'?'确认复位选定通道':'保存核查结论'}}</button></form></div></section></div></template>

<style scoped>
.instrument-controls .control-buttons .button{font-size:12px;line-height:1.6}

.instrument-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:8px}.instrument-heading h3{margin:0}.instrument-mode{color:#496b76;font-size:12px;line-height:1.7}.stop-command{color:inherit;background:#fff;border-color:#d8e5e8}.stop-command .ui-icon{width:13px;height:13px;margin-right:4px;vertical-align:-2px}
</style>
